struct TupleVarCount : HBUINT16
{
  bool has_shared_point_numbers () const { return ((*this) & SharedPointNumbers); }
  unsigned int get_count () const { return (*this) & CountMask; }

  protected:
  enum Flags
  {
    SharedPointNumbers  = 0x8000u,
    CountMask           = 0x0FFFu
  };

  public:
  DEFINE_SIZE_STATIC (2);
};

struct GlyphVarData
